/* Native choices make the six verified Side Jobs explicit. Drafts never write campaign records. */
(()=>{'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(window.UKI18n?.language==='en'?en:ko)}</span>`,rows=c=>(window.RULES_DATA?.sideJobs||[]).filter(r=>r.source_verified===true&&String(r.edition_slug||r.edition).toUpperCase()===String(c.edition).toUpperCase());
function option(value,en,ko,current,authored=false){return `<option value="${E(value)}" ${value===current?'selected':''} ${authored?'data-user-text':`data-i18n-en="${E(en)}" data-i18n-ko="${E(ko||en)}"`}>${E(authored||window.UKI18n?.language==='en'?en:ko||en)}</option>`;}
function nativeSelect(c,name,options,current,extra=''){const list=rows(c);return `<label class="wide cp-native-side-job"><span>${L('Side Job','사이드 잡')}</span><select name="${E(name)}" ${extra}>${options.map(([id,label])=>{const row=list.find(r=>r.id===id),builtin=id===''?['No Side Job','선택 안 함']:id==='custom'?['Custom','직접 입력']:id==='recorded'&&label==='Previously recorded Side Job'?['Previously recorded Side Job','기존 기록 유지']:null;return option(id,builtin?.[0]||row?.name||label,builtin?.[1]||row?.name_ko||label,current,id==='recorded'&&!builtin);}).join('')}</select></label>`;}
function description(row){if(!row)return '';const en=window.UK_CATALOG_LOCALE?.rulesEn?.['sideJobs:'+row.id]||row.description_en||row.description||'';return `<p>${L(en,row.description||en)}</p><button type="button" class="btn small" data-side-job-rule="${E(row.id)}">${L('Conditions & examples','달성 조건·예시')}</button>`;}
function report(c,p={}){const list=rows(c),id=p.sideJobId||p.side_job_id||'',name=p.sideJobName||p.side_job_name||'',legacy=p.sideJob||name,row=id?list.find(r=>r.id===id):list.find(r=>[r.name,r.name_ko].includes(legacy)),unknown=!!id&&!row,choice=row?.id||(unknown?'recorded':legacy?'custom':''),custom=row?'':legacy,options=[['','No Side Job'],...list.map(r=>[r.id,r.name]),...(unknown?[['recorded',legacy||'Previously recorded Side Job']]:[]),['custom','Custom']],original={sideJob:legacy,sideJobId:id,sideJobName:name};return `<div class="cp-side-job-picker" data-side-job-report data-side-job-edition="${E(c.edition)}" data-side-job-original="${E(JSON.stringify(original))}">${nativeSelect(c,'sideJobChoice',options,choice,'data-side-job-choice')}<input type="hidden" name="sideJob" value="${E(row?.name||legacy)}"><label data-side-job-custom ${choice==='custom'?'':'hidden'}>${L('Custom Side Job','직접 입력한 사이드 잡')}<input name="sideJobCustom" value="${E(custom)}" data-side-job-custom-name data-user-text></label><div class="cp-side-job-conditions" data-side-job-conditions ${row?'':'hidden'}>${description(row)}</div></div>`;}
function update(box){const choice=box.querySelector('[data-side-job-choice]').value,row=rows({edition:box.dataset.sideJobEdition}).find(r=>r.id===choice),custom=box.querySelector('[data-side-job-custom]'),input=box.querySelector('[data-side-job-custom-name]'),original=JSON.parse(box.dataset.sideJobOriginal),preview=box.querySelector('[data-side-job-conditions]');custom.hidden=choice!=='custom';box.querySelector('[name=sideJob]').value=row?.name||(choice==='custom'?input.value:choice==='recorded'?original.sideJob:'');preview.hidden=!row;preview.innerHTML=description(row);window.UKI18n?.refresh(box);}
function readReport(container){const box=container.querySelector('[data-side-job-report]');if(!box)return {sideJob:container.querySelector('[name=sideJob]')?.value||''};const choice=box.querySelector('[data-side-job-choice]').value,row=rows({edition:box.dataset.sideJobEdition}).find(r=>r.id===choice);if(choice==='recorded')return JSON.parse(box.dataset.sideJobOriginal);if(row)return {sideJob:row.name,sideJobId:row.id};const custom=choice==='custom'?box.querySelector('[data-side-job-custom-name]').value:'';return {sideJob:custom,...(custom?{sideJobName:custom}:{})};}
for(const name of ['change','input'])document.addEventListener(name,event=>{const box=event.target.closest('[data-side-job-report]');if(box&&(event.target.matches('[data-side-job-choice]')||event.target.matches('[data-side-job-custom-name]')))update(box);});
document.addEventListener('click',event=>{const button=event.target.closest('[data-side-job-rule]');if(!button)return;event.preventDefault();const box=button.closest('[data-side-job-report]');window.MMRuleReference?.open('sideJobs',button.dataset.sideJobRule,{edition:box?.dataset.sideJobEdition||'N26',activator:button});});
window.MMSideJobs={nativeSelect,report,readReport};
})();
